export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4);
  const g = Number(inputs.gravity ?? 9.8);

  const apexTime = u / g;
  const apexHeight = (u * u) / (2 * g);

  const t = Math.min(Math.max(0, time), 2 * apexTime);

  const tossedHeight = Math.max(0, u * t - 0.5 * g * t * t);
  const tossedVelocity = u - g * t;
  const tossedAcceleration = -g;

  const isReleased = t >= apexTime;
  const dropHeight = isReleased ? Math.max(0, apexHeight - 0.5 * g * (t - apexTime) * (t - apexTime)) : apexHeight;
  const dropVelocity = isReleased ? -g * (t - apexTime) : 0;
  const dropAcceleration = isReleased ? -g : 0;

  const y0 = 360;
  const pxPerM = 120;

  const tossY = y0 - tossedHeight * pxPerM;
  const dropY = y0 - dropHeight * pxPerM;
  const apexY = y0 - apexHeight * pxPerM;

  const tossLaneX = 40;
  const tossLaneW = 260;
  const tossBallX = tossLaneX + tossLaneW / 2;

  const dropLaneX = 340;
  const dropLaneW = 260;
  const dropBallX = dropLaneX + dropLaneW / 2;

  let tossState = "At launch";
  if (t === 0) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.005) tossState = "At the top";
  else if (t < apexTime) tossState = "Rising";
  else if (t >= 2 * apexTime - 0.005) tossState = "At launch height";
  else tossState = "Falling";

  let dropState = "Held in place";
  if (t < apexTime) dropState = "Held in place";
  else if (Math.abs(t - apexTime) < 0.005) dropState = "Just released";
  else if (t >= 2 * apexTime - 0.005) dropState = "At launch height";
  else dropState = "Falling together";

  const objects = [];

  const tossPanel = sdk.panel({
    id: "lane.toss",
    x: tossLaneX,
    y: 28,
    w: tossLaneW,
    h: 380,
    title: "Toss Lane",
    state: tossState
  });
  const dropPanel = sdk.panel({
    id: "lane.drop",
    x: dropLaneX,
    y: 28,
    w: dropLaneW,
    h: 380,
    title: "Drop Lane",
    state: dropState
  });
  objects.push(...tossPanel, ...dropPanel);

  objects.push(sdk.axis("axis.toss", {
    x: tossLaneX + 30,
    y: y0,
    length: 270,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.axis("axis.drop", {
    x: dropLaneX + 30,
    y: y0,
    length: 270,
    orientation: "y",
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: "Height",
    unit: "m"
  }));

  objects.push(sdk.groundMark("ground.toss", tossBallX, y0, 80, "Launch mark (0 m)"));
  objects.push(sdk.groundMark("ground.drop", dropBallX, y0, 80, "Launch mark (0 m)"));

  if (t >= apexTime) {
    objects.push(sdk.circle("apex.outline.toss", tossBallX, apexY, 24, { role: "neutral", opacity: 0.3 }));
    objects.push(sdk.circle("apex.outline.drop", dropBallX, apexY, 24, { role: "neutral", opacity: 0.3 }));
  }

  const gateObjs = sdk.gate("gate", dropBallX, apexY + 12, { open: isReleased, w: 40, label: "Release gate" });
  objects.push(...gateObjs);

  objects.push(sdk.circle("ball.toss", tossBallX, tossY, 24, { role: "learner" }));
  objects.push(sdk.circle("ball.drop", dropBallX, dropY, 24, { role: "learner" }));

  const vecVToss = sdk.vector("vec.v.toss", { x: tossBallX - 18, y: tossY }, {
    value: tossedVelocity,
    direction: "up",
    scale: 25,
    label: "v"
  });
  const vecAToss = sdk.vector("vec.a.toss", { x: tossBallX + 18, y: tossY }, {
    value: tossedAcceleration,
    direction: "up",
    scale: 8,
    label: "a"
  });
  const vecVDrop = sdk.vector("vec.v.drop", { x: dropBallX - 18, y: dropY }, {
    value: dropVelocity,
    direction: "up",
    scale: 25,
    label: "v"
  });
  const vecADrop = sdk.vector("vec.a.drop", { x: dropBallX + 18, y: dropY }, {
    value: dropAcceleration,
    direction: "up",
    scale: 8,
    label: "a"
  });
  objects.push(...vecVToss, ...vecAToss, ...vecVDrop, ...vecADrop);

  const calloutToss = sdk.callout(tossBallX + 45, tossY - 20, [
    `v: ${sdk.format(tossedVelocity, 2)} m/s`,
    `a: ${sdk.format(tossedAcceleration, 2)} m/s²`
  ], { id: "callout.toss" });

  const calloutDrop = sdk.callout(dropBallX + 45, dropY - 20, [
    `v: ${sdk.format(dropVelocity, 2)} m/s`,
    `a: ${sdk.format(dropAcceleration, 2)} m/s²`
  ], { id: "callout.drop" });

  objects.push(...calloutToss, ...calloutDrop);

  const frame = {
    width: 640,
    height: 420,
    objects,
    readouts: [
      { id: "tossedVelocity", value: tossedVelocity },
      { id: "tossedAcceleration", value: tossedAcceleration },
      { id: "dropVelocity", value: dropVelocity },
      { id: "dropAcceleration", value: dropAcceleration }
    ]
  };

  const quantities = {
    launchSpeed: u,
    gravity: g,
    apexTime,
    apexHeight,
    tossedVelocity,
    tossedAcceleration,
    tossedHeight,
    dropVelocity,
    dropAcceleration,
    dropHeight
  };

  return { frame, quantities };
}
